head.script:
scwin.fn_slideHide = function(e) {
	if (slideHide1.getUserData("edu_flag") == null) {
		slideHide1.setUserData("edu_flag", "y");
		slideHide1.startHide();
	} else {
		slideHide1.setUserData("edu_flag", null);
		slideHide1.startSlide();
	}
};
scwin.__isCloseToRight = function() {
	if (slideLeft == "auto") {
		return parseInt(((j) => j.length ? j : $('#mf_slideHide1'))($('#slideHide1')).css("left")) > 0;
	}
	return parseInt(((j) => j.length ? j : $('#mf_slideHide1'))($('#slideHide1')).css("left")) > parseInt(slideLeft);
};
scwin.onpageload = function() {
	window.slideLeft = ((j) => j.length ? j : $('#mf_slideHide1'))($('#slideHide1')).css("left");
};
